(474, 1, '7683891338357624072', 'https://www.tiktok.com/@benicecoffee_tanjunganom/video/7683891338357624072', 'benicecoffee_tanjunganom', 'Be Nice Coffee Tanjunganom', 'Bagus Dwi', 'Nama mungkin belum sebesar mereka, tapi rasa punya cerita sendiri. ☕ Cobain dulu kopi kami, baru nilai sendiri.  #benicecoffee #warujayeng #kulinerwarujayeng #tanjunganom_warujayeng ', '', 1789045370, 212, 8, 0, 0, '2026-09-25 02:29:21'),
